solution.javascript:
function retirerCadeau(liste, cadeau) {
  const apres = [...liste];
  const position = apres.indexOf(cadeau);
  if (position !== -1) {
    apres.splice(position, 1);
  }
  return { avant: liste, apres: apres };
}

