solution.javascript:
function historique(etat, modifs) {
  const estDico = (x) => typeof x === "object" && x !== null && !Array.isArray(x);
  function maj(noeud, chemin, valeur) {
    const [cle, ...reste] = chemin;
    const copie = { ...noeud };
    if (reste.length === 0) {
      if (valeur === null) {
        delete copie[cle];
      } else {
        copie[cle] = valeur;
      }
      return copie;
    }
    const enfant = copie[cle];
    if (valeur === null && !estDico(enfant)) {
      return noeud;
    }
    copie[cle] = maj(estDico(enfant) ? enfant : {}, reste, valeur);
    return copie;
  }
  const versions = [etat];
  let courant = etat;
  for (const [chemin, valeur] of modifs) {
    courant = maj(courant, chemin, valeur);
    versions.push(courant);
  }
  return versions;
}

solution.python:
def historique(etat, modifs):
    def maj(noeud, chemin, valeur):
        cle, reste = chemin[0], chemin[1:]
        copie = dict(noeud)
        if not reste:
            if valeur is None:
                copie.pop(cle, None)
            else:
                copie[cle] = valeur
            return copie
        enfant = copie.get(cle)
        if valeur is None and not isinstance(enfant, dict):
            return noeud
        copie[cle] = maj(enfant if isinstance(enfant, dict) else {}, reste, valeur)
        return copie

    versions = [etat]
    courant = etat
    for chemin, valeur in modifs:
        courant = maj(courant, chemin, valeur)
        versions.append(courant)
    return versions

